import{_ as o,o as r,c as a,ag as e}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"MiroFish：多智能体\\"万物预测引擎\\"评估","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-tools/mirofish-prediction-engine.md","filePath":"topics/ai-tools/mirofish-prediction-engine.md"}'),i={name:"topics/ai-tools/mirofish-prediction-engine.md"};function n(s,t,l,d,h,g){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="mirofish-多智能体-万物预测引擎-评估" tabindex="-1">MiroFish：多智能体&quot;万物预测引擎&quot;评估 <a class="header-anchor" href="#mirofish-多智能体-万物预测引擎-评估" aria-label="Permalink to &quot;MiroFish：多智能体&quot;万物预测引擎&quot;评估&quot;">​</a></h1><blockquote><p>评估日期：2026-08-16 全部数据来自 GitHub API / README 实测，非视频转述。视频宣传与实测对照见下。</p></blockquote><hr><h2 id="一、项目实况-github-api-实测-2026-08-16" tabindex="-1">一、项目实况（GitHub API 实测 2026-08-16） <a class="header-anchor" href="#一、项目实况-github-api-实测-2026-08-16" aria-label="Permalink to &quot;一、项目实况（GitHub API 实测 2026-08-16）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>实测</th></tr></thead><tbody><tr><td>仓库</td><td><code>666ghj/MiroFish</code></td></tr><tr><td>Stars</td><td><strong>70,987</strong>（视频说&quot;超62k&quot;——已超，属实）</td></tr><tr><td>Forks</td><td>11,057</td></tr><tr><td>开发语言</td><td>Python</td></tr><tr><td>许可证</td><td><strong>AGPL-3.0</strong> ⚠️</td></tr><tr><td>创建</td><td>2025-11-26</td></tr><tr><td>最后活跃</td><td>2026-08-16（仍在日常维护）</td></tr><tr><td>Open Issues</td><td>127</td></tr><tr><td>官方站点</td><td>mirofish.ai</td></tr></tbody></table><blockquote><p>视频出处：一位开发者用 10 天开发、《红楼梦》炫技、陈天桥 3000 万投资——<strong>详见第五节逐条核实</strong>。</p></blockquote><hr><h2 id="二、它到底是什么-readme-实测" tabindex="-1">二、它到底是什么（README 实测） <a class="header-anchor" href="#二、它到底是什么-readme-实测" aria-label="Permalink to &quot;二、它到底是什么（README 实测）&quot;">​</a></h2><p>官方定位：<strong>通用群体智能引擎，预测万物</strong>。工作方式：</p><ol><li><strong>图构建</strong>：从种子材料（新闻/政策/小说）提取实体&amp;关系，注入个体/集体记忆，建 GraphRAG</li><li><strong>环境设定</strong>：实体关系抽取 + 人物画像生成 + Agent 配置注入</li><li><strong>模拟</strong>：双平台并行模拟，自动解析预测需求，动态时间记忆更新</li><li><strong>报告生成</strong>：ReportAgent 用丰富工具与模拟后环境深度交互</li><li><strong>深度交互</strong>：可与模拟世界里任何 Agent 对话</li></ol><p><strong>技术底座（README 明确披露）</strong>：</p><ul><li><strong>模拟引擎基于 CAMEL-AI 的 <a href="https://github.com/camel-ai/oasis" target="_blank" rel="noreferrer">OASIS</a></strong>（开源，Apache-2.0，5027 star）——这是核心&quot;多智能体社会演化&quot;的底座，不是从零写的</li><li>LLM 走 OpenAI 兼容 API（README 推荐阿里 qwen-plus，并提示&quot;高消耗，先试少于40轮&quot;）</li><li>记忆用 <strong>Zep Cloud</strong>（付费，README 说免费额度够简单用）</li></ul><hr><h2 id="三、客观打折视角" tabindex="-1">三、客观打折视角 <a class="header-anchor" href="#三、客观打折视角" aria-label="Permalink to &quot;三、客观打折视角&quot;">​</a></h2><h3 id="优势-真实" tabindex="-1">优势（真实） <a class="header-anchor" href="#优势-真实" aria-label="Permalink to &quot;优势（真实）&quot;">​</a></h3><ul><li><strong>star 爆发力罕见</strong>：70k star / 2.8万 fork，说明关注度极高（虽含潮流成分）</li><li><strong>完整的演示闭环</strong>：官方提供武大舆情、红楼梦失传结局两个 demo 视频 + live demo</li><li><strong>真实工程可用</strong>：有源码部署 + Docker 两套方式，非 PPT 项目</li><li><strong>背靠资源</strong>：盛大集团战略孵化/投资</li></ul><h3 id="需要打折-警惕的" tabindex="-1">需要打折/警惕的 <a class="header-anchor" href="#需要打折-警惕的" aria-label="Permalink to &quot;需要打折/警惕的&quot;">​</a></h3><ol><li><strong>&quot;预测万物&quot;是营销语言</strong>：本质是<strong>语义合理的模拟</strong>，不是数学上可验证的预测。多智能体模拟的产出高度依赖种子材料质量与关键变量设定——<strong>任何&quot;预测报告&quot;都不能当事实依据</strong>（视频评论区网友也理性指出了这点）。</li><li><strong>成本不低</strong>：README 自己提示 LLM&quot;高消耗，大于40轮先别跑&quot;。真实跑一个有意义的推演，Token 成本不便宜（视频说红楼梦只要14元，大概率是特调的小用例）。</li><li><strong>依赖矩阵</strong>：它自己不是纯端到端，依赖 OASIS（模拟）+ Qwen（LLM）+ Zep（记忆）第三方。</li><li><strong>红学案例要理性看</strong>：推演&quot;与主流红学考证高度吻合&quot;——这更像说明<strong>喂进去的材料本身浓缩了主流红学观点</strong>（种子材料质量决定产出），而非引擎有神秘预测力。</li></ol><hr><h2 id="四、许可证合规提示-自托管关注点" tabindex="-1">四、许可证合规提示（自托管关注点） <a class="header-anchor" href="#四、许可证合规提示-自托管关注点" aria-label="Permalink to &quot;四、许可证合规提示（自托管关注点）&quot;">​</a></h2><ul><li><strong>AGPL-3.0</strong>：强传染性开源协议。<strong>若你基于它做修改并提供网络服务，需开源你的全部修改代码</strong>。对想商业化/闭源封装的人是个硬约束。</li><li>底层 OASIS 是 Apache-2.0（宽松），但 MiroFish 本体是 AGPL——<strong>用 MiroFish 的代码受 AGPL 约束</strong>。</li><li>若只把 MiroFish 当黑盒工具本地自用、不改代码，AGPL 约束较小；一旦集成进自研产品要谨慎。</li></ul><hr><h2 id="五、视频宣传逐条核实" tabindex="-1">五、视频宣传逐条核实 <a class="header-anchor" href="#五、视频宣传逐条核实" aria-label="Permalink to &quot;五、视频宣传逐条核实&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宣传点</th><th>实测</th></tr></thead><tbody><tr><td>GitHub 超 62k star</td><td>✅ 属实，实际 70k+</td></tr><tr><td>陈天桥/盛大 3000 万投资</td><td>⚠️ 盛大孵化/战略支持<strong>确凿</strong>（README 招聘邮箱 <a href="mailto:mirofish@shanda.com" target="_blank" rel="noreferrer">mirofish@shanda.com</a>、官方致谢段），但&quot;3000 万&quot;具体金额<strong>未在仓库源头确认</strong>，属媒体报道</td></tr><tr><td>00后开发者 10 天完成</td><td>⚠️ 作者 <code>666ghj</code> 的年龄/开发时长<strong>仓库无法核实</strong>，为媒体报道</td></tr><tr><td>《红楼梦》前80回推演失传结局</td><td>✅ 官方 demo 视频真实存在（B站 BV1cPk3BBExq），README 写明&quot;基于前80回数十万字推演失传结局&quot;</td></tr><tr><td>14 元成本</td><td>⚠️ 未在 README 确认，大概率是特调小用例的成本，不代表通用可复现</td></tr></tbody></table><p><strong>结论</strong>：核心数字（star、红学 demo、盛大支持）<strong>属实</strong>；人物细节与具体金额属<strong>媒体渲染</strong>，仓库层面无法独立证实。</p><hr><h2 id="六、一句话评估" tabindex="-1">六、一句话评估 <a class="header-anchor" href="#六、一句话评估" aria-label="Permalink to &quot;六、一句话评估&quot;">​</a></h2><p>MiroFish 是一个<strong>工程完整、传播极强、基于成熟开源组件(OASIS)的多智能体模拟引擎</strong>。它的价值在**&quot;创意推演/决策预演/思想实验&quot;层的模拟**，不是真正的预测——把它当&quot;假如……会怎样&quot;的沙盘助手用有价值，当&quot;算命的&quot;用会失望。</p><hr><h2 id="七、本地跑通成本评估-自托管视角-2026-08-16" tabindex="-1">七、本地跑通成本评估（自托管视角，2026-08-16） <a class="header-anchor" href="#七、本地跑通成本评估-自托管视角-2026-08-16" aria-label="Permalink to &quot;七、本地跑通成本评估（自托管视角，2026-08-16）&quot;">​</a></h2><p><strong>核心问题</strong>：官方版依赖 Zep Cloud（云记忆、付费）+ DashScope/qwen API（云 LLM）+ OpenAI 图。能否脱离云、纯本地跑？——<strong>可以，但靠社区 fork，官方版不支持纯本地。</strong></p><h3 id="官方版的最小可跑-最简-仍是半云" tabindex="-1">官方版的最小可跑（最简，仍是半云） <a class="header-anchor" href="#官方版的最小可跑-最简-仍是半云" aria-label="Permalink to &quot;官方版的最小可跑（最简，仍是半云）&quot;">​</a></h3><p><code>LLM_API_KEY + LLM_BASE_URL(DashScope) + ZEP_API_KEY(Zep Cloud)</code> → 记忆在图云、LLM 在阿里云，本地只跑前端+调度。<strong>不是自托管</strong>，只是把 UI 跑在本地。</p><h3 id="全本地方案-社区-fork-实测存在-非虚构" tabindex="-1">全本地方案：社区 fork（实测存在，非虚构） <a class="header-anchor" href="#全本地方案-社区-fork-实测存在-非虚构" aria-label="Permalink to &quot;全本地方案：社区 fork（实测存在，非虚构）&quot;">​</a></h3><p><strong>① nikmcfly/MiroFish-Offline</strong>（2.4k⭐，AGPL，2026-03 更新）</p><ul><li><strong>记忆</strong>：Zep Cloud → <strong>Neo4j CE 5.15</strong>（本地图库）</li><li><strong>LLM</strong>：DashScope → <strong>Ollama</strong>（qwen2.5:32b，可降 14b/7b）</li><li><strong>嵌入</strong>：Zep embeddings → <strong>nomic-embed-text</strong>（本地）</li><li><strong>前端</strong>：整站译成英文</li><li>一键 Docker Compose（Neo4j+Ollama+MiroFish 三条服务）</li></ul><p><strong>② tt-a1i/MiroFish-local</strong>（147⭐，AGPL）</p><ul><li>Zep → Graphiti + Neo4j；中文 UI 保留；主打&quot;简易本地跑通&quot;</li></ul><h3 id="硬件要求-offline-fork-官方表" tabindex="-1">硬件要求（Offline fork 官方表） <a class="header-anchor" href="#硬件要求-offline-fork-官方表" aria-label="Permalink to &quot;硬件要求（Offline fork 官方表）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>组件</th><th>最低</th><th>推荐</th></tr></thead><tbody><tr><td>RAM</td><td>16 GB</td><td>32 GB</td></tr><tr><td>VRAM (GPU)</td><td>10 GB (14b 模型)</td><td>24 GB (32b)</td></tr><tr><td>磁盘</td><td>20 GB</td><td>50 GB</td></tr><tr><td>CPU</td><td>4 核</td><td>8+ 核</td></tr></tbody></table><ul><li><strong>CPU-only 可跑</strong>，但模型推理明显慢；轻量场景用 qwen2.5:14b 或 7b</li><li><strong>⚠️ Mac 注意</strong>：VRAM 是 NVIDIA 系说法。Apple Silicon Mac 用 Ollama 走 MPS，推理速度可接受但不可直接拿&quot;NVIDIA 24GB VRAM&quot;对标；16GB 统一内存的 M 系列跑 qwen2.5:7b/14b 可行，32b 会吃紧。</li></ul><h3 id="本地化的隐性成本-别只盯硬件" tabindex="-1">本地化的隐性成本（别只盯硬件） <a class="header-anchor" href="#本地化的隐性成本-别只盯硬件" aria-label="Permalink to &quot;本地化的隐性成本（别只盯硬件）&quot;">​</a></h3><ol><li><strong>总 Token 消耗被转移到本地算力</strong>：多智能体&quot;1000 个 agent 自由交互&quot;意味着海量 LLM 推理——<strong>本地跑 1000 agent 几乎不现实</strong>（除非大批量降采样到几十个）。README 原版提示&quot;先试少于 40 轮&quot;，本地版同样受制于此。</li><li><strong>Neo4j + Ollama 两个常驻服务</strong>吃掉的内存，在 Mac 上叠加系统占用，实际可用 RAM 要再打折。</li><li><strong>模型质量降级</strong>：qwen2.5:32b 本地版 vs qwen-plus 云端版，语义推理质量有差距——&quot;推演输出&quot;的合理性会下降。</li><li><strong>AGPL 传染依旧存在</strong>：本地 fork 同样是 AGPL，集成进自研产品仍受约束。</li></ol><h3 id="对普通用户-非重度-ai-玩家-的诚实结论" tabindex="-1">对普通用户（非重度 AI 玩家）的诚实结论 <a class="header-anchor" href="#对普通用户-非重度-ai-玩家-的诚实结论" aria-label="Permalink to &quot;对普通用户（非重度 AI 玩家）的诚实结论&quot;">​</a></h3><ul><li><strong>想体验它的玩法</strong>：用<strong>官方提供的前 80 回/舆情 demo 视频 + live demo 网页</strong>就够，<strong>完全不用部署</strong>。</li><li><strong>真想本地折腾</strong>：只推荐给<strong>已有 32GB RAM + 还能接受常驻 Neo4j/Ollama 的机器</strong>、且对&quot;推演模拟&quot;是真需求的人。愿意的话用 Offline fork 的 Docker 一键起，别用官方版。</li><li><strong>性价比判断</strong>：它本质是<strong>思想实验沙盘</strong>，不是生产力刚需工具。若你只是想&quot;玩玩多智能体预测&quot;，本地部署的运维成本 &gt; 获得的边际价值——<strong>不值得为尝鲜而自托管</strong>；若你真有持续的&quot;预演决策/推演剧情&quot;需求，才值得。</li></ul><hr><h2 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词&quot;">​</a></h2><p>MiroFish、群体智能、多智能体、预测引擎、OASIS、CAMEL-AI、AGPL、盛大、红楼梦、数字沙盘、社会模拟、GraphRAG</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><p>ai-tools/index · ai-system-architecture/index（gearshaft 重构/工程） · investment-methods/index（理性评估）</p>',50)])])}const c=o(i,[["render",n]]);export{q as __pageData,c as default};
